insert into public.roles (key, display_name, description) values ('assistente-executivo', 'Assistente Executivo', 'Lê os e-mails novos, avisa no WhatsApp o que é importante, responde e marca reuniões com a sua confirmação.');
insert into public.role_versions (role_key, version, config, config_sha256) values ('assistente-executivo', 1, '{"canal_principal":"whatsapp","conexoes_obrigatorias":["google","whatsapp"],"descricao":"Lê os e-mails novos, avisa no WhatsApp o que é importante, responde e marca reuniões com a sua confirmação.","especialistas":{"secretaria":{"descricao":"Redige respostas de e-mail no tom do dono, consulta a agenda, propõe horários e prepara convites de reunião. Use quando o dono pedir para responder, marcar ou remarcar algo.","ferramentas":["calendar_alterar_evento","calendar_disponibilidade","contatos_buscar","gmail_ler","gmail_rascunhar","memoria_buscar"],"modelo":"claude-opus-5-5","prompt":"agents/secretaria/system.md"},"triagem":{"descricao":"Classifica e-mails recebidos por importância (alta, média, baixa), resume cada um em duas linhas e diz o motivo. Use para olhar a caixa de entrada; ela não responde nem age.","esforco":"low","ferramentas":["gmail_ler","gmail_listar_novos","regras_notificacao","salvar_triagem","whatsapp_avisar_dono"],"modelo":"claude-opus-5-5","prompt":"agents/triagem/system.md"}},"inclui":[],"key":"assistente-executivo","limites":{"chamadas_por_ferramenta_por_tarefa":40,"custo_maximo_usd_por_tarefa":2,"tentativas_por_tarefa":2,"turnos_maximos":40},"nome_exibicao":"Assistente Executivo","orquestrador":{"modelo":"claude-opus-5-5","prompt":"agents/orquestrador/system.md"},"permissoes":{"acoes":{"calendar.convidar":"confirmar","calendar.criar_evento":"automatico","gmail.enviar":"confirmar","memoria.registrar":"confirmar","whatsapp.avisar_dono":"automatico"},"acoes_proibidas":[]},"rotinas":[{"cron":"0 7 * * *","id":"resumo-diario","tarefa":"Monte o resumo do dia para o dono: compromissos de hoje e e-mails de importância média que ficaram para o resumo. Seja breve e mande pelo canal principal.","titulo":"Resumo do dia"},{"cron":"*/3 * * * *","id":"sincronizar-email","job":"gmail.sincronizar"}],"version":1}'::jsonb, 'e9647b9f8a55c43da4f4f1ba7a1d411f5a81e82c1a0f7d1359fedbeb33b1af9b');
insert into public.roles (key, display_name, description) values ('braco-direito', 'Braço Direito', 'Cuida do seu e-mail, da sua agenda e do Instagram da empresa. Você fala com ele pelo WhatsApp e confirma o que for importante.');
insert into public.role_versions (role_key, version, config, config_sha256) values ('braco-direito', 1, '{"canal_principal":"whatsapp","conexoes_obrigatorias":["google","instagram","whatsapp"],"descricao":"Cuida do seu e-mail, da sua agenda e do Instagram da empresa. Você fala com ele pelo WhatsApp e confirma o que for importante.","especialistas":{"copywriter":{"descricao":"Escreve textos no tom da marca: legendas, chamadas, mensagens. Use quando precisar de texto final ou de variações de um texto.","ferramentas":["memoria_buscar","politica_checar_texto"],"modelo":"claude-opus-5-5","prompt":"agents/copywriter/system.md"},"criativo":{"descricao":"Escolhe e adapta as imagens enviadas pelo dono (recorte por formato, texto sobre imagem) e escreve briefings visuais. Não gera imagens do zero.","ferramentas":["midia_listar"],"modelo":"claude-opus-5-5","prompt":"agents/criativo/system.md"},"secretaria":{"descricao":"Redige respostas de e-mail no tom do dono, consulta a agenda, propõe horários e prepara convites de reunião. Use quando o dono pedir para responder, marcar ou remarcar algo.","ferramentas":["calendar_alterar_evento","calendar_disponibilidade","contatos_buscar","gmail_ler","gmail_rascunhar","memoria_buscar"],"modelo":"claude-opus-5-5","prompt":"agents/secretaria/system.md"},"social":{"descricao":"Decide formato, horário e estrutura de posts do Instagram e prepara a publicação. Use para qualquer pedido de post, carrossel, reels ou story, e para o planejamento da semana.","ferramentas":["instagram_insights","instagram_listar_posts","instagram_preparar_post","memoria_buscar","midia_listar"],"modelo":"claude-opus-5-5","prompt":"agents/social/system.md"},"triagem":{"descricao":"Classifica e-mails recebidos por importância (alta, média, baixa), resume cada um em duas linhas e diz o motivo. Use para olhar a caixa de entrada; ela não responde nem age.","esforco":"low","ferramentas":["gmail_ler","gmail_listar_novos","regras_notificacao","salvar_triagem","whatsapp_avisar_dono"],"modelo":"claude-opus-5-5","prompt":"agents/triagem/system.md"}},"inclui":["assistente-executivo","social-media"],"key":"braco-direito","limites":{"chamadas_por_ferramenta_por_tarefa":30,"custo_maximo_usd_por_tarefa":3,"tentativas_por_tarefa":2,"turnos_maximos":40},"nome_exibicao":"Braço Direito","orquestrador":{"esforco":"high","modelo":"claude-opus-5-5","prompt":"agents/orquestrador/system.md"},"permissoes":{"acoes":{"calendar.convidar":"confirmar","calendar.criar_evento":"automatico","gmail.enviar":"confirmar","instagram.publicar":"confirmar","memoria.registrar":"confirmar","whatsapp.avisar_dono":"automatico"},"acoes_proibidas":[]},"rotinas":[{"cron":"0 7 * * *","id":"resumo-diario","tarefa":"Monte o resumo do dia para o dono: compromissos de hoje e e-mails de importância média que ficaram para o resumo. Seja breve e mande pelo canal principal.","titulo":"Resumo do dia"},{"cron":"*/3 * * * *","id":"sincronizar-email","job":"gmail.sincronizar"},{"agente_inicial":"social","cron":"0 9 * * 1","id":"planejamento-semanal","tarefa":"Proponha os posts desta semana para o Instagram da empresa: tema, formato e dia de cada um, considerando datas relevantes e o que funcionou nas últimas semanas. Não publique nada: mande a proposta para o dono escolher.","titulo":"Planejamento de posts da semana"}],"version":1}'::jsonb, 'cf30222033d37fdd6f3a69fab163b3168afde1387662237ea62d4bb7e13ad9f5');
insert into public.roles (key, display_name, description) values ('social-media', 'Social Media', 'Planeja, escreve e prepara posts do Instagram. Você manda o comando (e a foto, se tiver) e confirma a prévia com um toque.');
insert into public.role_versions (role_key, version, config, config_sha256) values ('social-media', 1, '{"canal_principal":"whatsapp","conexoes_obrigatorias":["instagram","whatsapp"],"descricao":"Planeja, escreve e prepara posts do Instagram. Você manda o comando (e a foto, se tiver) e confirma a prévia com um toque.","especialistas":{"copywriter":{"descricao":"Escreve textos no tom da marca: legendas, chamadas, mensagens. Use quando precisar de texto final ou de variações de um texto.","ferramentas":["memoria_buscar","politica_checar_texto"],"modelo":"claude-opus-5-5","prompt":"agents/copywriter/system.md"},"criativo":{"descricao":"Escolhe e adapta as imagens enviadas pelo dono (recorte por formato, texto sobre imagem) e escreve briefings visuais. Não gera imagens do zero.","ferramentas":["midia_listar"],"modelo":"claude-opus-5-5","prompt":"agents/criativo/system.md"},"social":{"descricao":"Decide formato, horário e estrutura de posts do Instagram e prepara a publicação. Use para qualquer pedido de post, carrossel, reels ou story, e para o planejamento da semana.","ferramentas":["instagram_insights","instagram_listar_posts","instagram_preparar_post","memoria_buscar","midia_listar"],"modelo":"claude-opus-5-5","prompt":"agents/social/system.md"}},"inclui":[],"key":"social-media","limites":{"chamadas_por_ferramenta_por_tarefa":30,"custo_maximo_usd_por_tarefa":3,"tentativas_por_tarefa":2,"turnos_maximos":40},"nome_exibicao":"Social Media","orquestrador":{"modelo":"claude-opus-5-5","prompt":"agents/orquestrador/system.md"},"permissoes":{"acoes":{"instagram.publicar":"confirmar","memoria.registrar":"confirmar"},"acoes_proibidas":[]},"rotinas":[{"agente_inicial":"social","cron":"0 9 * * 1","id":"planejamento-semanal","tarefa":"Proponha os posts desta semana para o Instagram da empresa: tema, formato e dia de cada um, considerando datas relevantes e o que funcionou nas últimas semanas. Não publique nada: mande a proposta para o dono escolher.","titulo":"Planejamento de posts da semana"}],"version":1}'::jsonb, 'c407ea4f285ecfd29269d803d1a4267c52b0d1c3ae45abf446d03d1bb0494e5d');
